// Parse incoming appointment booking details and determine the best email template
const source = ($json.body && typeof $json.body === 'object' && !Array.isArray($json.body))
  ? $json.body
  : (($json.query && typeof $json.query === 'object' && !Array.isArray($json.query))
    ? $json.query
    : ($json ?? {}));

const text = (v) => v == null ? '' : String(v).trim();
const customerName = text(source.customer_name || source.client_name || source.patient_name || source.name) || 'Valued Patient';
const customerEmail = text(source.customer_email || source.client_email || source.patient_email || source.recipient || source.email).toLowerCase();
const customerPhone = text(source.customer_phone || source.client_phone || source.phone);

const serviceName = text(source.service_name || source.meeting_topic || source.service || source.topic || source.title) || 'Doctor Consultation & General Checkup';
const clinicName = text(source.clinic_name || source.business_name || source.company_name || source.host_name) || 'CareSync Medical Clinic';
const doctorName = text(source.doctor_name || source.specialist_name || source.practitioner_name || source.host_name);
const location = text(source.location || source.address || source.clinic_address) || 'Main Health Plaza, Suite 402, Islamabad';
const appointmentId = text(source.appointment_id || source.booking_id || source.id) || ('APT-' + Math.random().toString(36).substring(2, 9).toUpperCase());
const timezone = text(source.timezone || source.time_zone) || 'Asia/Karachi';
const durationMinutes = Number(source.duration_minutes || source.duration || 30);
const notes = text(source.notes || source.agenda || source.instructions || source.description);
const senderEmail = text(source.sender_email || source.host_email) || 'sardarumairnawazkhan@gmail.com';

// Parse Date and Time
let apptDate = text(source.appointment_date || source.meeting_date || source.date);
let apptTime = text(source.appointment_time || source.meeting_time || source.time);
const startTimeRaw = text(source.start_time || source.startTime || source.start_datetime);

if ((!apptDate || !apptTime) && startTimeRaw) {
  try {
    const d = new Date(startTimeRaw);
    if (!Number.isNaN(d.getTime())) {
      const parts = Object.fromEntries(new Intl.DateTimeFormat('en-CA', {
        timeZone: timezone,
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        hourCycle: 'h23'
      }).formatToParts(d).filter(p => p.type !== 'literal').map(p => [p.type, p.value]));
      apptDate = apptDate || `${parts.year}-${parts.month}-${parts.day}`;
      apptTime = apptTime || `${parts.hour}:${parts.minute}`;
    }
  } catch(e) {}
}

if (!apptDate) {
  const tomorrow = new Date(Date.now() + 86400000);
  apptDate = tomorrow.toISOString().split('T')[0];
}
if (!apptTime) {
  apptTime = '11:00';
}

// Automatic Template Selection
let templateType = text(source.template_type || source.template).toLowerCase();
if (!templateType) {
  const combined = (serviceName + ' ' + clinicName).toLowerCase();
  if (combined.includes('wellness') || combined.includes('spa') || combined.includes('massage') || combined.includes('yoga') || combined.includes('therapy')) {
    templateType = 'wellness_session';
  } else if (combined.includes('zoom') || combined.includes('meet') || combined.includes('video') || combined.includes('online')) {
    templateType = 'video_meeting';
  } else if (combined.includes('doctor') || combined.includes('clinic') || combined.includes('medical') || combined.includes('health') || combined.includes('dental') || combined.includes('consult')) {
    templateType = 'medical_consultation';
  } else {
    templateType = 'general_appointment';
  }
}

const errors = [];
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailRegex.test(customerEmail)) {
  errors.push({ field: 'customer_email', message: 'A valid email address is required.' });
}

return [{
  json: {
    valid: errors.length === 0,
    errors,
    appointment: {
      customer_name: customerName,
      customer_email: customerEmail,
      customer_phone: customerPhone,
      service_name: serviceName,
      clinic_name: clinicName,
      doctor_name: doctorName,
      location,
      appointment_id: appointmentId,
      appointment_date: apptDate,
      appointment_time: apptTime,
      start_time: startTimeRaw,
      timezone,
      duration_minutes: durationMinutes,
      notes,
      sender_email: senderEmail,
      template_type: templateType,
      attach_ics: source.attach_ics !== false
    }
  }
}];

return [{
  json: {
    success: false,
    workflow: 'confirmation_email_agent',
    status: 'VALIDATION_ERROR',
    message: 'The confirmation email could not be sent because required fields are missing or invalid.',
    errors: $json.errors
  }
}];

// Generate RFC-5545 compliant .ics calendar invitation and create n8n binary attachment
const appt = $('Select Template & Parse Appointment Data').first().json.appointment;

const pad = (v) => String(v).padStart(2, '0');
const compactUtc = (d) => d.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}Z$/, 'Z');
const escapeIcs = (v) => String(v ?? '').replace(/\\/g, '\\\\').replace(/\n/g, '\\n').replace(/,/g, '\\,').replace(/;/g, '\\;');

let dtStart, dtEnd;
const startTimeParsed = appt.start_time ? new Date(appt.start_time) : null;
if (startTimeParsed && !Number.isNaN(startTimeParsed.getTime())) {
  dtStart = 'DTSTART:' + compactUtc(startTimeParsed);
  dtEnd = 'DTEND:' + compactUtc(new Date(startTimeParsed.getTime() + appt.duration_minutes * 60000));
} else {
  const localStart = new Date(appt.appointment_date + 'T' + appt.appointment_time + ':00Z');
  const localEnd = new Date(localStart.getTime() + appt.duration_minutes * 60000);
  const compactLocal = (d) => d.getUTCFullYear() + pad(d.getUTCMonth() + 1) + pad(d.getUTCDate()) + 'T' + pad(d.getUTCHours()) + pad(d.getUTCMinutes()) + pad(d.getUTCSeconds());
  dtStart = 'DTSTART;TZID=' + appt.timezone + ':' + compactLocal(localStart);
  dtEnd = 'DTEND;TZID=' + appt.timezone + ':' + compactLocal(localEnd);
}

const icsContent = [
  'BEGIN:VCALENDAR',
  'VERSION:2.0',
  'PRODID:-//' + escapeIcs(appt.clinic_name) + '//Appointment Assistant//EN',
  'CALSCALE:GREGORIAN',
  'METHOD:REQUEST',
  'BEGIN:VEVENT',
  'UID:' + escapeIcs(appt.appointment_id) + '@caresync.health',
  'DTSTAMP:' + compactUtc(new Date()),
  dtStart,
  dtEnd,
  appt.sender_email ? 'ORGANIZER;CN=' + escapeIcs(appt.clinic_name) + ':mailto:' + escapeIcs(appt.sender_email) : '',
  'ATTENDEE;CN=' + escapeIcs(appt.customer_name) + ';RSVP=TRUE:mailto:' + escapeIcs(appt.customer_email),
  'SUMMARY:' + escapeIcs(appt.service_name + ' — ' + appt.clinic_name),
  'DESCRIPTION:' + escapeIcs('Appointment Reference: ' + appt.appointment_id + '\\nPatient: ' + appt.customer_name + '\\nService: ' + appt.service_name + '\\nLocation: ' + appt.location + (appt.notes ? '\\nNotes: ' + appt.notes : '')),
  'LOCATION:' + escapeIcs(appt.location),
  'STATUS:CONFIRMED',
  'END:VEVENT',
  'END:VCALENDAR'
].filter(Boolean).join('\r\n');

const icsBase64 = Buffer.from(icsContent, 'utf8').toString('base64');
const icsFilename = 'appointment-' + appt.appointment_id.replace(/[^a-z0-9_-]/gi, '-') + '.ics';

return [{
  json: {
    appointment: appt,
    calendar_attachment: {
      binary_property: 'calendar_invite',
      filename: icsFilename,
      content_type: 'text/calendar; charset=utf-8; method=REQUEST',
      content_base64: icsBase64
    }
  },
  binary: {
    calendar_invite: {
      data: icsBase64,
      mimeType: 'text/calendar',
      fileName: icsFilename,
      fileExtension: 'ics'
    }
  }
}];

// Render a responsive HTML email message based on the chosen template type
const appt = $json.appointment;
const escapeHtml = (v) => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

// Format Date & Time nicely
let displayDate = appt.appointment_date;
try {
  displayDate = new Intl.DateTimeFormat('en-US', {
    dateStyle: 'full',
    timeZone: 'UTC'
  }).format(new Date(appt.appointment_date + 'T00:00:00Z'));
} catch(e) {}

let displayTime = appt.appointment_time;
try {
  const parts = appt.appointment_time.split(':');
  if (parts.length >= 2) {
    const h = parseInt(parts[0], 10);
    const m = parts[1].slice(0, 2);
    displayTime = `${h % 12 || 12}:${m} ${h >= 12 ? 'PM' : 'AM'}`;
  }
} catch(e) {}

// Google Calendar 1-Click Link
const gCalStart = appt.appointment_date.replace(/-/g, '') + 'T' + appt.appointment_time.replace(/:/g, '').slice(0, 4) + '00';
const gCalEnd = appt.appointment_date.replace(/-/g, '') + 'T' + (parseInt(appt.appointment_time.replace(/:/g, '').slice(0, 4), 10) + 30) + '00';
const gCalTitle = encodeURIComponent(`${appt.service_name} — ${appt.clinic_name}`);
const gCalDetails = encodeURIComponent(`Appointment Ref: ${appt.appointment_id}\nPatient: ${appt.customer_name}\nService: ${appt.service_name}\nLocation: ${appt.location}`);
const gCalLoc = encodeURIComponent(appt.location);
const gCalUrl = `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${gCalTitle}&dates=${gCalStart}/${gCalEnd}&details=${gCalDetails}&location=${gCalLoc}`;

// Template Theme Settings
const templateConfigs = {
  medical_consultation: {
    primaryColor: '#0284c7',
    badgeText: 'Medical Consultation Confirmed',
    headerIcon: '🏥',
    heroTitle: 'Your Consultation is Confirmed',
    instructionTitle: 'Medical & Consultation Guidelines',
    instructions: 'Please arrive 10 minutes prior to your scheduled consultation time. Bring your national ID, insurance card, and any recent lab or medical test reports.',
    accentBg: '#eff6ff',
    accentBorder: '#3b82f6',
    cardBg: '#f8fafc'
  },
  wellness_session: {
    primaryColor: '#10b981',
    badgeText: 'Wellness Session Reserved',
    headerIcon: '🌿',
    heroTitle: 'Your Wellness Session is Reserved',
    instructionTitle: 'Session Preparation',
    instructions: 'Please wear comfortable attire and arrive 10 minutes early to check in and relax in our quiet lounge before your session.',
    accentBg: '#ecfdf5',
    accentBorder: '#10b981',
    cardBg: '#f0fdf4'
  },
  video_meeting: {
    primaryColor: '#4f46e5',
    badgeText: 'Video Meeting Scheduled',
    headerIcon: '💻',
    heroTitle: 'Your Video Meeting is Scheduled',
    instructionTitle: 'Video Call Instructions',
    instructions: 'Please test your audio and camera beforehand and join using the link 5 minutes prior to the start time.',
    accentBg: '#eef2ff',
    accentBorder: '#4f46e5',
    cardBg: '#f8fafc'
  },
  general_appointment: {
    primaryColor: '#0f172a',
    badgeText: 'Appointment Confirmed',
    headerIcon: '🗓️',
    heroTitle: 'Your Appointment is Confirmed',
    instructionTitle: 'Important Reminders',
    instructions: 'Please keep this confirmation handy. A calendar invite is attached for your Google, Apple, or Outlook calendar.',
    accentBg: '#f1f5f9',
    accentBorder: '#0f172a',
    cardBg: '#ffffff'
  }
};

const config = templateConfigs[appt.template_type] || templateConfigs.general_appointment;

const detailRow = (icon, label, value) => !value ? '' : `
  <tr>
    <td style="padding:9px 0;color:#64748b;font-size:14px;width:38%;vertical-align:top;">
      <span style="display:inline-block;width:20px;">${icon}</span> ${escapeHtml(label)}:
    </td>
    <td style="padding:9px 0;color:#0f172a;font-weight:600;font-size:14px;vertical-align:top;">
      ${escapeHtml(value)}
    </td>
  </tr>
`;

const html = `<!doctype html>
<html>
<head>
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <style>
    @media only screen and (max-width: 620px) {
      .container-table { width: 100% !important; }
      .body-content { padding: 26px 18px !important; }
      .cal-btn { display: block !important; text-align: center !important; }
    }
  </style>
</head>
<body style="margin:0;padding:0;background:#f1f5f9;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#0f172a;">
  <table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#f1f5f9;padding:32px 12px;">
    <tr>
      <td align="center">
        <table role="presentation" class="container-table" width="620" cellspacing="0" cellpadding="0" style="width:100%;max-width:620px;background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 12px 35px rgba(15,23,42,0.08);border:1px solid #e2e8f0;">
          <!-- Top Accent Bar -->
          <tr><td style="height:6px;background:${config.primaryColor};"></td></tr>

          <!-- Clinic / Company Header -->
          <tr>
            <td style="padding:24px 36px;border-bottom:1px solid #e2e8f0;background:#ffffff;">
              <table role="presentation" width="100%" cellspacing="0" cellpadding="0">
                <tr>
                  <td>
                    <div style="font-size:20px;font-weight:800;color:${config.primaryColor};letter-spacing:-0.02em;">
                      ${config.headerIcon} ${escapeHtml(appt.clinic_name)}
                    </div>
                  </td>
                  <td align="right">
                    <span style="font-size:11px;font-weight:700;letter-spacing:0.06em;text-transform:uppercase;background:${config.accentBg};color:${config.primaryColor};padding:4px 10px;border-radius:12px;border:1px solid ${config.primaryColor};">
                      ✓ Verified Booking
                    </span>
                  </td>
                </tr>
              </table>
            </td>
          </tr>

          <!-- Main Body -->
          <tr>
            <td class="body-content" style="padding:36px 36px 28px;">
              <div style="font-size:12px;font-weight:800;letter-spacing:0.12em;text-transform:uppercase;color:${config.primaryColor};margin-bottom:12px;">
                ${config.badgeText}
              </div>
              <h1 style="margin:0 0 16px;font-size:27px;color:#0f172a;line-height:1.25;letter-spacing:-0.02em;">
                ${config.heroTitle}
              </h1>
              <p style="margin:0 0 16px;font-size:15px;line-height:1.7;color:#475569;">
                Hi <strong>${escapeHtml(appt.customer_name)}</strong>,
              </p>
              <p style="margin:0 0 24px;font-size:15px;line-height:1.7;color:#475569;">
                Your appointment at <strong>${escapeHtml(appt.clinic_name)}</strong> has been scheduled and confirmed. Below is your official consultation summary:
              </p>

              <!-- Highlighted Appointment Card -->
              <div style="background:${config.cardBg};border:1.5px solid #e2e8f0;border-radius:14px;padding:22px 24px;margin:22px 0;">
                <div style="font-size:16px;font-weight:800;color:#0f172a;margin-bottom:14px;border-bottom:1px solid #e2e8f0;padding-bottom:10px;display:flex;justify-content:space-between;">
                  <span>📋 Reference: <strong style="color:${config.primaryColor};">#${escapeHtml(appt.appointment_id)}</strong></span>
                </div>
                <table role="presentation" width="100%" cellspacing="0" cellpadding="0">
                  ${detailRow('🩺', 'Service', appt.service_name)}
                  ${appt.doctor_name ? detailRow('👨‍⚕️', 'Specialist', appt.doctor_name) : ''}
                  ${detailRow('📅', 'Date', displayDate)}
                  ${detailRow('⏰', 'Time', `${displayTime} (${appt.timezone})`)}
                  ${detailRow('⏱️', 'Duration', `${appt.duration_minutes} Minutes`)}
                  ${detailRow('👤', 'Patient', appt.customer_name)}
                  ${detailRow('📍', 'Location', appt.location)}
                  ${appt.customer_phone ? detailRow('📞', 'Contact Phone', appt.customer_phone) : ''}
                </table>
              </div>

              <!-- 1-Click Calendar Add Button -->
              <table role="presentation" cellspacing="0" cellpadding="0" style="margin:20px 0 24px;">
                <tr>
                  <td>
                    <a href="${gCalUrl}" target="_blank" class="cal-btn" style="display:inline-block;padding:12px 22px;border-radius:10px;background:${config.primaryColor};color:#ffffff;text-decoration:none;font-size:14px;font-weight:700;box-shadow:0 4px 12px rgba(2,132,199,0.28);">
                      📅 Add to Google Calendar
                    </a>
                  </td>
                </tr>
              </table>

              <!-- Calendar Invite Notice -->
              <div style="padding:16px 20px;background:${config.accentBg};border-radius:10px;border-left:4px solid ${config.accentBorder};color:#1e3a8a;font-size:13.5px;line-height:1.6;margin:20px 0;">
                <strong>📅 Calendar Invite Attached (.ics):</strong><br>
                A standard calendar invitation (<code>appointment-${escapeHtml(appt.appointment_id)}.ics</code>) is attached to this email. Opening it will automatically add this appointment to your Google Calendar, Apple Calendar, or Outlook schedule.
              </div>

              <!-- Preparation & Guidance Box -->
              <div style="padding:16px 20px;background:#f8fafc;border-radius:10px;border:1px solid #e2e8f0;font-size:13.5px;line-height:1.6;color:#334155;margin:20px 0;">
                <strong>💡 ${config.instructionTitle}:</strong><br>
                ${escapeHtml(appt.notes || config.instructions)}
              </div>

              <p style="margin:24px 0 0;font-size:15px;line-height:1.7;color:#475569;">
                Looking forward to your visit,<br>
                <strong>${escapeHtml(appt.clinic_name)} Team</strong>
              </p>
            </td>
          </tr>

          <!-- Footer -->
          <tr>
            <td style="padding:22px 36px;background:#0f172a;color:#94a3b8;font-size:12px;line-height:1.7;text-align:center;">
              ${escapeHtml(appt.clinic_name)} • ${escapeHtml(appt.location)}<br>
              Need to reschedule or have questions? Contact us at <a href="mailto:${escapeHtml(appt.sender_email)}" style="color:#38bdf8;">${escapeHtml(appt.sender_email)}</a>.
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>
</body>
</html>`;

const subject = `Your Appointment is Confirmed 🎉 | ${displayDate} at ${displayTime} — ${appt.clinic_name}`;

return [{
  json: {
    appointment: appt,
    template_used: appt.template_type,
    recipient: appt.customer_email,
    subject,
    html,
    sender_name: appt.clinic_name,
    attach_ics: appt.attach_ics
  },
  binary: $input.item.binary
}];

const input = $input.item;
const prep = input.json;
return [{
  json: {
    ...prep,
    client_email_message: {
      sender_name: prep.sender_name,
      recipient: prep.recipient,
      subject: prep.subject,
      html: prep.html,
      attachment_binary_property: prep.attach_ics ? 'calendar_invite' : ''
    }
  },
  binary: input.binary
}];

const response = $json ?? {};
const prep = $('Prepare Client Gmail Message').first().json;
const gmailError = response.error?.message ?? response.error ?? '';
const sent = !gmailError && Boolean(response.id || response.threadId);

return [{
  json: {
    success: sent,
    workflow: 'confirmation_email_agent',
    status: sent ? 'DELIVERED' : 'FAILED',
    recipient: prep.recipient,
    subject: prep.subject,
    template_used: prep.template_used,
    appointment_id: prep.appointment.appointment_id,
    appointment_date: prep.appointment.appointment_date,
    appointment_time: prep.appointment.appointment_time,
    service_name: prep.appointment.service_name,
    clinic_name: prep.appointment.clinic_name,
    calendar_invite_attached: prep.attach_ics,
    gmail_message_id: response.id || null,
    error: sent ? null : (gmailError || 'Gmail sending failed'),
    message: sent
      ? 'Confirmation email with calendar invite delivered successfully via Gmail.'
      : 'Failed to deliver confirmation email via Gmail: ' + gmailError
  }
}];
